insert into public.business_settings(name) select 'La Forneria Basso' where not exists(select 1 from public.business_settings);
insert into public.inventory_items(product_id,unit,quantity,minimum_quantity,allow_negative) select id,case when category='desserts' then 'pote' else 'unidade' end,0,0,false from public.products where stock_tracked on conflict(product_id) do nothing;
